---@class CPayActivityPkHandler : CPacketHandlers
local PayActivityPkHandler = T(Global, "PacketHandlers")

function PayActivityPkHandler:onCreatePayActivity(packet)
    self.payActivity:createActivity(packet.activityId, packet.data)
end

function PayActivityPkHandler:onRemovePayActivity(packet)
    self.payActivity:removeActivity(packet.activityId)
end

function PayActivityPkHandler:runPayActivityFunc(packet)
    local activity = self.payActivity.activities[packet.activityId]
    if not activity then
        return
    end
    activity:runClientFunc(packet.name, table.unpack(packet.params))
end

function PayActivityPkHandler:syncPayActivityData(packet)
    local result = packet.result
    for activityId, values in pairs(result) do
        local activity = self.payActivity.activities[activityId]
        if activity then
            activity.info:setValues(values)
        end
    end
end

function PayActivityPkHandler:onGetPayActivityReward(packet)
    if packet.params and packet.params.delay then
        LuaTimer:scheduleTimer(function()
            UIHelper.showGameGUILayout(packet.ui or "GUIPayActivityRewardResult", packet.rewards,packet.params)
        end, packet.params.delay,1)
    else
        UIHelper.showGameGUILayout(packet.ui or "GUIPayActivityRewardResult", packet.rewards,packet.params)
    end
end

function PayActivityPkHandler:onShowToast(packet)
    if packet and packet.strKey then
        UIHelper.showToast(Lang:getString(packet.strKey))
    end
end

function PayActivityPkHandler:onDrawResult()
    Events.PayActivityDrawResult:invoke()
end

function PayActivityPkHandler:onGetWatchAdCache()
    --ClientHelper.callAppJsonFunction("getWatchAdCache", {
